/**
 * PLC Studio — generování zdrojových souborů programu pro cílové platformy.
 * Siemens: SCL (external sources) + SimaticML XML + TSV tagů.
 * Ostatní: IEC 61131-3 ST + platformní soubor tagů (GVL / CSV / tab).
 */
import { Project, PlatformKey } from "./model.js";
export declare const SCL_MOTOR = "FUNCTION_BLOCK \"FB_Motor\"\n{ S7_Optimized_Access := 'TRUE' }\nVERSION : 0.1\n// \u0160ablona: motor/\u010Derpadlo se zp\u011Btn\u00FDm hl\u00E1\u0161en\u00EDm b\u011Bhu\nVAR_INPUT\n    enable : Bool;\n    cmdStart : Bool;\n    cmdStop : Bool;\n    fbkRunning : Bool;\n    fault : Bool;\nEND_VAR\nVAR_OUTPUT\n    outRun : Bool;\n    busy : Bool;\n    error : Bool;\n    status : Word;\nEND_VAR\nVAR\n    statStep : Int;\n    instTrigStart : R_TRIG;\n    instTrigStop : R_TRIG;\n    instTonFbk : TON;\nEND_VAR\nVAR CONSTANT\n    STEP_IDLE : Int := 0;\n    STEP_STARTING : Int := 10;\n    STEP_RUNNING : Int := 20;\n    STEP_ERROR : Int := 90;\n    T_FBK : Time := T#3S;\nEND_VAR\n\nBEGIN\n    IF NOT #enable THEN\n        #outRun := FALSE; #busy := FALSE; #error := FALSE;\n        #status := 16#8001; #statStep := #STEP_IDLE;\n        RETURN;\n    END_IF;\n\n    #instTrigStart(CLK := #cmdStart);\n    #instTrigStop(CLK := #cmdStop);\n\n    CASE #statStep OF\n        #STEP_IDLE:\n            #outRun := FALSE;\n            IF #instTrigStart.Q THEN #statStep := #STEP_STARTING; END_IF;\n        #STEP_STARTING:\n            #outRun := TRUE;\n            IF #fbkRunning THEN #statStep := #STEP_RUNNING; END_IF;\n        #STEP_RUNNING:\n            #outRun := TRUE;\n            IF NOT #fbkRunning THEN #statStep := #STEP_ERROR; END_IF;\n            IF #instTrigStop.Q THEN #statStep := #STEP_IDLE; END_IF;\n        #STEP_ERROR:\n            #outRun := FALSE;\n            IF #instTrigStop.Q AND NOT #fault THEN #statStep := #STEP_IDLE; END_IF;\n    END_CASE;\n\n    #instTonFbk(IN := (#statStep = #STEP_STARTING), PT := #T_FBK);\n    IF #instTonFbk.Q OR #fault THEN #statStep := #STEP_ERROR; END_IF;\n\n    #busy := (#statStep = #STEP_STARTING);\n    #error := (#statStep = #STEP_ERROR);\n    IF #error THEN #status := 16#8002; ELSE #status := 16#0000; END_IF;\nEND_FUNCTION_BLOCK";
export declare const SCL_VENTIL = "FUNCTION_BLOCK \"FB_Ventil\"\n{ S7_Optimized_Access := 'TRUE' }\nVERSION : 0.1\n// \u0160ablona: dvoupolohov\u00FD ventil/v\u00E1lec s koncov\u00FDmi sn\u00EDma\u010Di\nVAR_INPUT\n    enable : Bool;\n    cmdOpen : Bool;\n    cmdClose : Bool;\n    fbkOpen : Bool;\n    fbkClosed : Bool;\nEND_VAR\nVAR_OUTPUT\n    outOpen : Bool;\n    busy : Bool;\n    error : Bool;\n    status : Word;\nEND_VAR\nVAR\n    statStep : Int;\n    instTrigOpen : R_TRIG;\n    instTrigClose : R_TRIG;\n    instTonTravel : TON;\nEND_VAR\nVAR CONSTANT\n    STEP_CLOSED : Int := 0;\n    STEP_OPENING : Int := 10;\n    STEP_OPEN : Int := 20;\n    STEP_CLOSING : Int := 30;\n    STEP_ERROR : Int := 90;\n    T_TRAVEL : Time := T#5S;\nEND_VAR\n\nBEGIN\n    IF NOT #enable THEN\n        #outOpen := FALSE; #busy := FALSE; #error := FALSE;\n        #status := 16#8001; #statStep := #STEP_CLOSED;\n        RETURN;\n    END_IF;\n\n    #instTrigOpen(CLK := #cmdOpen);\n    #instTrigClose(CLK := #cmdClose);\n\n    CASE #statStep OF\n        #STEP_CLOSED:\n            #outOpen := FALSE;\n            IF #instTrigOpen.Q THEN #statStep := #STEP_OPENING; END_IF;\n        #STEP_OPENING:\n            #outOpen := TRUE;\n            IF #fbkOpen THEN #statStep := #STEP_OPEN; END_IF;\n        #STEP_OPEN:\n            #outOpen := TRUE;\n            IF #instTrigClose.Q THEN #statStep := #STEP_CLOSING; END_IF;\n        #STEP_CLOSING:\n            #outOpen := FALSE;\n            IF #fbkClosed THEN #statStep := #STEP_CLOSED; END_IF;\n        #STEP_ERROR:\n            #outOpen := FALSE;\n            IF #instTrigClose.Q THEN #statStep := #STEP_CLOSED; END_IF;\n    END_CASE;\n\n    #instTonTravel(IN := (#statStep = #STEP_OPENING) OR (#statStep = #STEP_CLOSING),\n                   PT := #T_TRAVEL);\n    IF #instTonTravel.Q THEN #statStep := #STEP_ERROR; END_IF;\n\n    #busy := (#statStep = #STEP_OPENING) OR (#statStep = #STEP_CLOSING);\n    #error := (#statStep = #STEP_ERROR);\n    IF #error THEN #status := 16#8002; ELSE #status := 16#0000; END_IF;\nEND_FUNCTION_BLOCK";
export declare const SCL_AI = "FUNCTION_BLOCK \"FB_AnalogIn\"\n{ S7_Optimized_Access := 'TRUE' }\nVERSION : 0.1\n// \u0160ablona: analogov\u00FD vstup se \u0161k\u00E1lov\u00E1n\u00EDm a mezemi (surov\u00E1 hodnota 0..27648)\nVAR_INPUT\n    rawValue : Int;\n    scaleMin : Real := 0.0;\n    scaleMax : Real := 100.0;\n    limitHi : Real := 1.0E+6;\n    limitLo : Real := -1.0E+6;\nEND_VAR\nVAR_OUTPUT\n    value : Real;\n    alarmHi : Bool;\n    alarmLo : Bool;\nEND_VAR\n\nBEGIN\n    #value := INT_TO_REAL(#rawValue) / 27648.0\n              * (#scaleMax - #scaleMin) + #scaleMin;\n    #alarmHi := #value > #limitHi;\n    #alarmLo := #value < #limitLo;\nEND_FUNCTION_BLOCK";
export declare const SCL_AO = "FUNCTION_BLOCK \"FB_AnalogOut\"\n{ S7_Optimized_Access := 'TRUE' }\nVERSION : 0.1\n// \u0160ablona: analogov\u00FD v\u00FDstup \u2014 in\u017Een\u00FDrsk\u00E9 jednotky -> surov\u00E1 hodnota 0..27648\nVAR_INPUT\n    value : Real;\n    scaleMin : Real := 0.0;\n    scaleMax : Real := 100.0;\nEND_VAR\nVAR_OUTPUT\n    rawValue : Int;\nEND_VAR\n\nBEGIN\n    #rawValue := REAL_TO_INT(\n        (#value - #scaleMin) / (#scaleMax - #scaleMin) * 27648.0);\nEND_FUNCTION_BLOCK";
export declare const ST_MOTOR = "FUNCTION_BLOCK FB_Motor\n(* Sablona: motor/cerpadlo se zpetnym hlasenim behu *)\nVAR_INPUT\n    enable : BOOL;\n    cmdStart : BOOL;\n    cmdStop : BOOL;\n    fbkRunning : BOOL;\n    fault : BOOL;\nEND_VAR\nVAR_OUTPUT\n    outRun : BOOL;\n    busy : BOOL;\n    error : BOOL;\n    status : WORD;\nEND_VAR\nVAR\n    statStep : INT;\n    lastStart : BOOL;\n    lastStop : BOOL;\n    trigStart : BOOL;\n    trigStop : BOOL;\n    tonFbk : TON;\nEND_VAR\n\nIF NOT enable THEN\n    outRun := FALSE; busy := FALSE; error := FALSE;\n    status := 16#8001; statStep := 0;\n    RETURN;\nEND_IF;\n\n(* detekce hran *)\ntrigStart := cmdStart AND NOT lastStart;  lastStart := cmdStart;\ntrigStop  := cmdStop  AND NOT lastStop;   lastStop  := cmdStop;\n\nCASE statStep OF\n    0: (* IDLE *)\n        outRun := FALSE;\n        IF trigStart THEN statStep := 10; END_IF\n    10: (* STARTING *)\n        outRun := TRUE;\n        IF fbkRunning THEN statStep := 20; END_IF\n    20: (* RUNNING *)\n        outRun := TRUE;\n        IF NOT fbkRunning THEN statStep := 90; END_IF\n        IF trigStop THEN statStep := 0; END_IF\n    90: (* ERROR *)\n        outRun := FALSE;\n        IF trigStop AND NOT fault THEN statStep := 0; END_IF\nEND_CASE;\n\ntonFbk(IN := (statStep = 10), PT := T#3S);\nIF tonFbk.Q OR fault THEN statStep := 90; END_IF;\n\nbusy := (statStep = 10);\nerror := (statStep = 90);\nIF error THEN status := 16#8002; ELSE status := 16#0000; END_IF;\nEND_FUNCTION_BLOCK";
export declare const ST_VENTIL = "FUNCTION_BLOCK FB_Ventil\n(* Sablona: dvoupolohovy ventil/valec s koncovymi snimaci *)\nVAR_INPUT\n    enable : BOOL;\n    cmdOpen : BOOL;\n    cmdClose : BOOL;\n    fbkOpen : BOOL;\n    fbkClosed : BOOL;\nEND_VAR\nVAR_OUTPUT\n    outOpen : BOOL;\n    busy : BOOL;\n    error : BOOL;\n    status : WORD;\nEND_VAR\nVAR\n    statStep : INT;\n    lastOpen : BOOL;\n    lastClose : BOOL;\n    trigOpen : BOOL;\n    trigClose : BOOL;\n    tonTravel : TON;\nEND_VAR\n\nIF NOT enable THEN\n    outOpen := FALSE; busy := FALSE; error := FALSE;\n    status := 16#8001; statStep := 0;\n    RETURN;\nEND_IF;\n\ntrigOpen  := cmdOpen  AND NOT lastOpen;   lastOpen  := cmdOpen;\ntrigClose := cmdClose AND NOT lastClose;  lastClose := cmdClose;\n\nCASE statStep OF\n    0: (* CLOSED *)\n        outOpen := FALSE;\n        IF trigOpen THEN statStep := 10; END_IF\n    10: (* OPENING *)\n        outOpen := TRUE;\n        IF fbkOpen THEN statStep := 20; END_IF\n    20: (* OPEN *)\n        outOpen := TRUE;\n        IF trigClose THEN statStep := 30; END_IF\n    30: (* CLOSING *)\n        outOpen := FALSE;\n        IF fbkClosed THEN statStep := 0; END_IF\n    90: (* ERROR *)\n        outOpen := FALSE;\n        IF trigClose THEN statStep := 0; END_IF\nEND_CASE;\n\ntonTravel(IN := (statStep = 10) OR (statStep = 30), PT := T#5S);\nIF tonTravel.Q THEN statStep := 90; END_IF;\n\nbusy := (statStep = 10) OR (statStep = 30);\nerror := (statStep = 90);\nIF error THEN status := 16#8002; ELSE status := 16#0000; END_IF;\nEND_FUNCTION_BLOCK";
export declare const ST_AI = "FUNCTION_BLOCK FB_AnalogIn\n(* Sablona: analogovy vstup se skalovanim a mezemi.\n   rawMax uprav dle platformy: Siemens 27648, Beckhoff 32767,\n   Mitsubishi FX5 16000, Rockwell dle modulu. *)\nVAR_INPUT\n    rawValue : INT;\n    rawMax : INT := 27648;\n    scaleMin : REAL := 0.0;\n    scaleMax : REAL := 100.0;\n    limitHi : REAL := 1.0E+6;\n    limitLo : REAL := -1.0E+6;\nEND_VAR\nVAR_OUTPUT\n    value : REAL;\n    alarmHi : BOOL;\n    alarmLo : BOOL;\nEND_VAR\n\nvalue := INT_TO_REAL(rawValue) / INT_TO_REAL(rawMax)\n         * (scaleMax - scaleMin) + scaleMin;\nalarmHi := value > limitHi;\nalarmLo := value < limitLo;\nEND_FUNCTION_BLOCK";
export declare const ST_AO = "FUNCTION_BLOCK FB_AnalogOut\n(* Sablona: analogovy vystup \u2014 inzenyrske jednotky -> surova hodnota *)\nVAR_INPUT\n    value : REAL;\n    rawMax : INT := 27648;\n    scaleMin : REAL := 0.0;\n    scaleMax : REAL := 100.0;\nEND_VAR\nVAR_OUTPUT\n    rawValue : INT;\nEND_VAR\n\nrawValue := REAL_TO_INT((value - scaleMin) / (scaleMax - scaleMin)\n            * INT_TO_REAL(rawMax));\nEND_FUNCTION_BLOCK";
